package config;
import static org.junit.jupiter.api.Assertions.*;import java.util.Map;import org.junit.jupiter.api.Test;
class ConfiguracionMercadoPagoTest {@Test void deshabilitadaNoExigeSecretos(){var c=ConfiguracionMercadoPago.desde(Map.of("MP_ENABLED","false"));assertFalse(c.disponible());assertFalse(c.toString().contains("token"));}@Test void habilitadaExigeConfiguracionCompleta(){assertThrows(IllegalStateException.class,()->ConfiguracionMercadoPago.desde(Map.of("MP_ENABLED","true")));}@Test void completaGeneraRutasSeguras(){var c=ConfiguracionMercadoPago.desde(Map.of("MP_ENABLED","true","MP_ACCESS_TOKEN","TEST-secreto","MP_WEBHOOK_SECRET","firma","MP_PUBLIC_BASE_URL","https://club.example","MP_TEST_USER_ID","123","MP_ENVIRONMENT","sandbox"));assertTrue(c.disponible());assertEquals("https",c.webhookUrl().getScheme());assertTrue(c.webhookUrl().toString().endsWith("/api/publica/pagos/mercado-pago/webhook"));assertFalse(c.toString().contains("TEST-secreto"));}@Test void produccionRechazaHttp(){assertThrows(IllegalStateException.class,()->ConfiguracionMercadoPago.desde(Map.of("MP_ENABLED","true","MP_ACCESS_TOKEN","x","MP_WEBHOOK_SECRET","y","MP_PUBLIC_BASE_URL","http://club.example","MP_ENVIRONMENT","production")));}@org.junit.jupiter.api.Test void exigeVendedorEsperadoEnSandbox(){java.util.Map<String,String> v=new java.util.HashMap<>();v.put("MP_ENABLED","true");v.put("MP_ACCESS_TOKEN","APP_USR-prueba");v.put("MP_WEBHOOK_SECRET","secreto");v.put("MP_PUBLIC_BASE_URL","https://ejemplo.test");v.put("MP_ENVIRONMENT","sandbox");org.junit.jupiter.api.Assertions.assertThrows(IllegalStateException.class,()->ConfiguracionMercadoPago.desde(v));}
}
